{"command":"cat > main.go <<'GO'
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"sort"
	"strconv"
	"strings"

	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
)

// global flag variables
var (
	backendFlag      string
	s3BucketFlag     string
	kmsAliasFlag     string
	retriesFlag      int
	retryModeFlag    string
	verboseFlag      bool

	// validated values after env override
	currentBackend string
	currentS3Bucket string
)

// helper to get flag changed status
func isChanged(cmd *cobra.Command, name string) bool {
	return cmd.Root().PersistentFlags().Changed(name) || cmd.Flags().Changed(name)
}

// custom value for import normalize-keys to have type "chamber write"
type chamberWriteValue struct {
	val bool
}

func (c *chamberWriteValue) String() string {
	if c.val {
		return "true"
	}
	return "false"
}
func (c *chamberWriteValue) Set(s string) error {
	if s == "" {
		c.val = true
		return nil
	}
	b, err := strconv.ParseBool(s)
	if err != nil {
		// treat any value as true for --normalize-keys without arg?
		c.val = true
		return nil
	}
	c.val = b
	return nil
}
func (c *chamberWriteValue) Type() string { return "chamber write" }

// for write tags
var writeTags map[string]string
var writeSingleline bool
var writeSkipUnchanged bool

// for read
var readQuiet bool
var readVersion int

// for list
var listExpand bool
var listTime bool
var listUser bool
var listVersionSort bool

// for list-services
var listServicesSecrets bool

// for env
var envPreserveCase bool
var envEscapeStrings bool

// for export
var exportFormat string
var exportOutputFile string

// for find
var findByValue bool

// for delete
var deleteExactKey bool

// for import
var importNormalizeKeys chamberWriteValue

// for tag write
var tagWriteDeleteOther bool

// for exec
var execPristine bool
var execStrict bool
var execStrictValue string

func validateGlobals(cmd *cobra.Command) error {
	// handle env overrides if flag not changed
	if !cmd.Root().PersistentFlags().Changed("backend") {
		if v := os.Getenv("CHAMBER_SECRET_BACKEND"); v != "" {
			backendFlag = v
		}
	}
	if !cmd.Root().PersistentFlags().Changed("backend-s3-bucket") {
		if v := os.Getenv("CHAMBER_S3_BUCKET"); v != "" {
			s3BucketFlag = v
		}
	}
	if !cmd.Root().PersistentFlags().Changed("kms-key-alias") {
		if v := os.Getenv("CHAMBER_KMS_KEY_ALIAS"); v != "" {
			kmsAliasFlag = v
		}
	}
	if !cmd.Root().PersistentFlags().Changed("retries") {
		if v := os.Getenv("CHAMBER_RETRIES"); v != "" {
			i, err := strconv.Atoi(v)
			if err != nil {
				return fmt.Errorf("invalid argument %q for \"-r, --retries\" flag: %v", v, err)
			}
			retriesFlag = i
		}
	}
	// retry-mode has no env per help, but we could check CHAMBER_RETRY_MODE if set
	// not needed

	// normalize backend
	currentBackend = strings.ToLower(backendFlag)
	currentS3Bucket = s3BucketFlag

	valid := map[string]bool{"null": true, "ssm": true, "secretsmanager": true, "s3": true, "s3-kms": true}
	if !valid[currentBackend] {
		return fmt.Errorf("Failed to get secret store: invalid backend `%s`", strings.ToUpper(backendFlag))
	}
	if currentBackend == "s3" || currentBackend == "s3-kms" {
		if currentS3Bucket == "" {
			return fmt.Errorf("Failed to get secret store: Must set bucket for s3 backend")
		}
	}
	if retryModeFlag != "standard" && retryModeFlag != "adaptive" {
		if currentBackend != "null" {
			return fmt.Errorf("Failed to get secret store: Invalid retry mode %s", retryModeFlag)
		}
	}
	return nil
}

func main() {
	rootCmd := &cobra.Command{
		Use:   "chamber",
		Short: "CLI for storing secrets",
		PersistentPreRunE: func(cmd *cobra.Command, args []string) error {
			// skip validation for help and completion and version? But original allows those even with invalid backend.
			// Tests showed `version` with invalid backend still succeeded, and `completion` also.
			// So we should not validate for version and completion and help.
			// Check command path
			// If command is version, completion, help, or __complete, skip validation.
			name := cmd.Name()
			if name == "version" || name == "completion" || name == "help" || strings.HasPrefix(name, "__") {
				return nil
			}
			// Also if parent is completion (bash, zsh...), skip
			if cmd.Parent() != nil && cmd.Parent().Name() == "completion" {
				return nil
			}
			return validateGlobals(cmd)
		},
		SilenceErrors: false,
		SilenceUsage:  false,
	}

	// global flags
	rootCmd.PersistentFlags().StringVarP(&backendFlag, "backend", "b", "ssm", "Backend to use; AKA $CHAMBER_SECRET_BACKEND\n\tnull: no-op\n\tssm: SSM Parameter Store\n\tsecretsmanager: Secrets Manager\n\ts3: S3; requires --backend-s3-bucket\n\ts3-kms: S3 using AWS-KMS encryption; requires --backend-s3-bucket and --kms-key-alias set (if you want to write or delete keys).")
	rootCmd.PersistentFlags().StringVar(&s3BucketFlag, "backend-s3-bucket", "", "bucket for S3 backend; AKA $CHAMBER_S3_BUCKET")
	rootCmd.PersistentFlags().StringVar(&kmsAliasFlag, "kms-key-alias", "alias/parameter_store_key", "KMS Key Alias for writing and deleting secrets; AKA $CHAMBER_KMS_KEY_ALIAS. This option is currently only supported for the S3-KMS backend.")
	rootCmd.PersistentFlags().IntVarP(&retriesFlag, "retries", "r", 10, "For SSM or Secrets Manager, the number of retries we'll make before giving up; AKA $CHAMBER_RETRIES")
	rootCmd.PersistentFlags().StringVar(&retryModeFlag, "retry-mode", "standard", "For SSM, the model used to retry requests\n\t standard\n\t adaptive")
	rootCmd.PersistentFlags().BoolVar(&verboseFlag, "verbose", false, "Print more information to STDERR")

	// version
	versionCmd := &cobra.Command{
		Use:   "version",
		Short: "print version",
		Args:  cobra.MaximumNArgs(1),
		Run: func(cmd *cobra.Command, args []string) {
			fmt.Fprintln(os.Stdout, "chamber dev")
		},
	}
	// Need to skip validation for version: already handled in PersistentPreRunE but also need to allow invalid backend.
	// Override PersistentPreRunE for version to not validate
	versionCmd.PersistentPreRunE = func(cmd *cobra.Command, args []string) error { return nil }

	// write
	writeCmd := &cobra.Command{
		Use:   "write <service> <key> [--] <value|->",
		Short: "write a secret",
		Args:  cobra.ExactArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				// check tags
				if len(writeTags) > 0 {
					return fmt.Errorf("WriteWithTags is not implemented for Null Store")
				}
				// handle reading from stdin if value is "-"
				// but we still error
				return fmt.Errorf("Write is not implemented for Null Store")
			}
			// non-null: simulate AWS error
			// For write, original with ssm gave "operation error SSM: GetParameters, get identity: ..."
			return fmt.Errorf("operation error SSM: GetParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	writeCmd.Flags().BoolVarP(&writeSingleline, "singleline", "s", false, "Insert single line parameter (end with \\n)")
	writeCmd.Flags().BoolVar(&writeSkipUnchanged, "skip-unchanged", false, "Skip writing secret if value is unchanged")
	writeCmd.Flags().StringToStringVarP(&writeTags, "tags", "t", nil, "Add tags to the secret; new secrets only")

	// read
	readCmd := &cobra.Command{
		Use:   "read <service> <key>",
		Short: "Read a specific secret from the parameter store",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				return fmt.Errorf("Failed to read: Not implemented for Null Store")
			}
			return fmt.Errorf("Failed to read: operation error SSM: GetParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	readCmd.Flags().BoolVarP(&readQuiet, "quiet", "q", false, "Only print the secret")
	readCmd.Flags().IntVarP(&readVersion, "version", "v", -1, "The version number of the secret. Defaults to latest.")

	// list
	listCmd := &cobra.Command{
		Use:   "list <service>",
		Short: "List the secrets set for a service",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				if listExpand {
					fmt.Fprintln(os.Stdout, "Key\tVersion\t\tLastModified\tUser\tValue")
				} else {
					fmt.Fprintln(os.Stdout, "Key\tVersion\t\tLastModified\tUser")
				}
				return nil
			}
			return fmt.Errorf("Failed to list store contents: operation error SSM: DescribeParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	listCmd.Flags().BoolVarP(&listExpand, "expand", "e", false, "Expand parameter list with values")
	listCmd.Flags().BoolVarP(&listTime, "time", "t", false, "Sort by modified time")
	listCmd.Flags().BoolVarP(&listUser, "user", "u", false, "Sort by user")
	listCmd.Flags().BoolVarP(&listVersionSort, "version", "v", false, "Sort by version")

	// list-services
	listServicesCmd := &cobra.Command{
		Use:   "list-services <service>",
		Short: "List services",
		Args:  cobra.ArbitraryArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				fmt.Fprintln(os.Stdout, "Service")
				return nil
			}
			return fmt.Errorf("Failed to list store contents: operation error SSM: DescribeParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	listServicesCmd.Flags().BoolVarP(&listServicesSecrets, "secrets", "s", false, "Include secret names in the list")
	// allow max 1? But we already Arbitrary; help says <service> [flags] but we allow any.

	// history
	historyCmd := &cobra.Command{
		Use:   "history <service> <key>",
		Short: "View the history of a secret",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				fmt.Fprintln(os.Stdout, "Event\tVersion\t\tDate\tUser")
				return nil
			}
			return fmt.Errorf("Failed to get history: secret not found")
		},
	}

	// exec
	execCmd := &cobra.Command{
		Use:   "exec <service...> -- <command> [<arg...>]",
		Short: "Executes a command with secrets loaded into the environment",
		Long: `Executes a command with secrets loaded into the environment

Examples:

Given a secret store like this:

	$ echo '{"db_username": "root", "db_password": "hunter22"}' | chamber import - 

--strict will fail with unfilled env vars

	$ HOME=/tmp DB_USERNAME=chamberme DB_PASSWORD=chamberme EXTRA=chamberme chamber exec --strict service exec -- env
	chamber: extra unfilled env var EXTRA
	exit 1

--pristine takes effect after checking for --strict values

	$ HOME=/tmp DB_USERNAME=chamberme DB_PASSWORD=chamberme chamber exec --strict --pristine service exec -- env
	DB_USERNAME=root
	DB_PASSWORD=hunter22`,
		RunE: func(cmd *cobra.Command, args []string) error {
			// Custom args handling is via Args function, but we also need to handle here.
			// This will only be called if Args validation passed.
			dashIdx := cmd.ArgsLenAtDash()
			// dashIdx is index where -- exists, but args passed to RunE are already split without dash?
			// In Cobra, args contains all args without the --, but ArgsLenAtDash tells where dash was.
			// Actually cobra docs: ArgsLenAtDash returns length of args before dash, -1 if no dash.
			// So services = args[:dashIdx], command = args[dashIdx:]
			var services []string
			var command []string
			if dashIdx == -1 {
				// should not happen because Args would have failed
				return fmt.Errorf("please separate services and command with '--'. See usage")
			}
			services = args[:dashIdx]
			command = args[dashIdx:]
			if len(services) == 0 {
				return fmt.Errorf("at least one service must be specified: requires at least 1 arg(s), only received 0")
			}
			if len(command) == 0 {
				return fmt.Errorf("must specify command to run. See usage: requires at least 1 arg(s), only received 0")
			}
			// handle strict mode
			if execStrict {
				// collect env vars where value == strictValue
				// For null backend, secrets are empty, so any matching env var is missing.
				// Need to implement random selection among missing vars.
				// Build map of matching env vars
				matching := make(map[string]string)
				for _, kv := range os.Environ() {
					parts := strings.SplitN(kv, "=", 2)
					if len(parts) != 2 {
						continue
					}
					k, v := parts[0], parts[1]
					if v == execStrictValue {
						matching[k] = v
					}
				}
				// For null store, secrets empty, so all matching are missing.
				// For non-null, we would have secrets but we treat similarly for now.
				// If matching not empty, pick one random (map iteration random) and error.
				if len(matching) > 0 {
					// Convert to slice and pick random? But Go map iteration is random, so just iterate and pick first.
					// However to simulate randomness across runs, we can iterate over map directly.
					for k, v := range matching {
						// For null, always missing. For non-null, we would check if secret exists, but we assume missing.
						return fmt.Errorf("parent env was expecting %s=%s, but was not in store", k, v)
					}
				}
			}
			// Prepare env for command
			var env []string
			if execPristine {
				env = []string{}
				// but need to inject secrets (for null, none). For non-null, would inject but we skip.
				// Keep env empty except maybe we should not include anything.
			} else {
				env = os.Environ()
				// inject secrets would be added here; for null, none.
			}
			// For non-null, we would fetch secrets for each service and add to env.
			// But for this reimplementation, we treat non-null as not having secrets (since we don't actually fetch), so strict already would have triggered if needed.
			// So env remains as above.

			// Execute command
			c := exec.Command(command[0], command[1:]...)
			c.Env = env
			c.Stdin = os.Stdin
			c.Stdout = os.Stdout
			c.Stderr = os.Stderr
			err := c.Run()
			if err != nil {
				if exitErr, ok := err.(*exec.ExitError); ok {
					// propagate exit code
					os.Exit(exitErr.ExitCode())
				}
				// else error like executable not found
				return err
			}
			return nil
		},
	}
	// custom Args for exec to handle dash validation
	execCmd.Args = func(cmd *cobra.Command, args []string) error {
		dashIdx := cmd.ArgsLenAtDash()
		if dashIdx == -1 {
			return fmt.Errorf("please separate services and command with '--'. See usage")
		}
		services := args[:dashIdx]
		command := args[dashIdx:]
		if len(services) == 0 {
			return fmt.Errorf("at least one service must be specified: requires at least 1 arg(s), only received 0")
		}
		if len(command) == 0 {
			return fmt.Errorf("must specify command to run. See usage: requires at least 1 arg(s), only received 0")
		}
		return nil
	}
	execCmd.Flags().BoolVar(&execPristine, "pristine", false, "only use variables retrieved from the backend; do not inherit existing environment variables")
	execCmd.Flags().BoolVar(&execStrict, "strict", false, "enable strict mode:\nonly inject secrets for which there is a corresponding env var with value\n<strict-value>, and fail if there are any env vars with that value missing\nfrom secrets")
	execCmd.Flags().StringVar(&execStrictValue, "strict-value", "chamberme", "value to expect in --strict mode")

	// env
	envCmd := &cobra.Command{
		Use:   "env <service>",
		Short: "Print the secrets from the parameter store in a format to export as environment variables",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				// empty output
				return nil
			}
			return fmt.Errorf("Failed to list store contents: operation error SSM: GetParametersByPath, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	envCmd.Flags().BoolVarP(&envPreserveCase, "preserve-case", "p", false, "preserve variable name case")
	envCmd.Flags().BoolVarP(&envEscapeStrings, "escape-strings", "e", false, "escape special characters in values")

	// export
	exportCmd := &cobra.Command{
		Use:   "export <service...>",
		Short: "Exports parameters in the specified format",
		Args:  cobra.MinimumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			allowed := map[string]bool{"json": true, "yaml": true, "java-properties": true, "csv": true, "tsv": true, "dotenv": true, "tfvars": true}
			if !allowed[exportFormat] {
				return fmt.Errorf("Unable to export parameters: Unsupported export format: %s", exportFormat)
			}
			if exportOutputFile != "" {
				f, err := os.Create(exportOutputFile)
				if err != nil {
					return fmt.Errorf("Failed to open output file for writing: %v", err)
				}
				defer f.Close()
				if currentBackend == "null" {
					if exportFormat == "json" || exportFormat == "yaml" {
						fmt.Fprintln(f, "{}")
					} else {
						// empty
					}
					return nil
				}
				// non-null: credential error
				return fmt.Errorf("Failed to list store contents for service %s: operation error SSM: GetParametersByPath, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded", args[0])
			} else {
				if currentBackend == "null" {
					if exportFormat == "json" || exportFormat == "yaml" {
						fmt.Fprintln(os.Stdout, "{}")
					} else {
						// empty, no output
					}
					return nil
				}
				return fmt.Errorf("Failed to list store contents for service %s: operation error SSM: GetParametersByPath, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded", args[0])
			}
		},
	}
	exportCmd.Flags().StringVarP(&exportFormat, "format", "f", "json", "Output format (json, yaml, java-properties, csv, tsv, dotenv, tfvars)")
	exportCmd.Flags().StringVarP(&exportOutputFile, "output-file", "o", "", "Output file (default is standard output)")

	// find
	findCmd := &cobra.Command{
		Use:   "find <secret name>",
		Short: "Find the given secret across all services",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				if findByValue {
					fmt.Fprintln(os.Stdout, "Service\t\tKey")
				} else {
					fmt.Fprintln(os.Stdout, "Service")
				}
				return nil
			}
			return fmt.Errorf("Failed to list store contents: operation error SSM: DescribeParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	findCmd.Flags().BoolVarP(&findByValue, "by-value", "v", false, "Find parameters by value")

	// delete
	deleteCmd := &cobra.Command{
		Use:   "delete <service> <key>",
		Short: "Delete a secret, including all versions",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				return fmt.Errorf("Not implemented for Null Store")
			}
			return fmt.Errorf("operation error SSM: GetParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	deleteCmd.Flags().BoolVar(&deleteExactKey, "exact-key", false, "Prevent normalization of the provided key in order to delete any keys that match the exact provided casing.")

	// import
	importCmd := &cobra.Command{
		Use:   "import <service> <file|->",
		Short: "import secrets from json or yaml",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			file := args[1]
			if file == "-" {
				// read stdin
				_, err := io.ReadAll(os.Stdin)
				if err != nil {
					return fmt.Errorf("Failed to read stdin: %v", err)
				}
				if currentBackend == "null" {
					return fmt.Errorf("Failed to write secret: Write is not implemented for Null Store")
				}
				return fmt.Errorf("Failed to write secret: operation error SSM: GetParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
			}
			// try to open file
			f, err := os.Open(file)
			if err != nil {
				return fmt.Errorf("Failed to open file: %v", err)
			}
			defer f.Close()
			data, err := io.ReadAll(f)
			if err != nil {
				return fmt.Errorf("Failed to read file: %v", err)
			}
			// try to parse as json/yaml to validate? For null, we just return write error regardless.
			// But we should check if file contains valid json/yaml for non-null? Not needed.
			// If file empty or invalid, still write error for null.
			_ = data
			// also handle normalize-keys flag (no effect for null)
			if currentBackend == "null" {
				return fmt.Errorf("Failed to write secret: Write is not implemented for Null Store")
			}
			return fmt.Errorf("Failed to write secret: operation error SSM: GetParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	// custom flag for normalize-keys with type "chamber write"
	importCmd.Flags().Var(&importNormalizeKeys, "normalize-keys", "Normalize keys to match how chamber write would handle them. If not specified, keys will be written exactly how they are defined in the import source.")

	// tag
	tagCmd := &cobra.Command{
		Use:   "tag",
		Short: "work with tags on secrets",
	}
	tagReadCmd := &cobra.Command{
		Use:   "read <service> <key>",
		Short: "Read tags for a specific secret",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				return fmt.Errorf("Failed to read tags: Not implemented for Null Store")
			}
			return fmt.Errorf("Failed to read tags: operation error SSM: ListTagsForResource, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	tagWriteCmd := &cobra.Command{
		Use:   "write <service> <key> <tag>...",
		Short: "Write tags for a specific secret",
		Args:  cobra.MinimumNArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				return fmt.Errorf("Failed to write tags: Not implemented for Null Store")
			}
			return fmt.Errorf("Failed to write tags: operation error SSM: AddTagsToResource, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	tagWriteCmd.Flags().BoolVar(&tagWriteDeleteOther, "delete-other-tags", false, "Delete tags not specified in the command")
	tagDeleteCmd := &cobra.Command{
		Use:   "delete <service> <key> <tag key>...",
		Short: "Delete tags for a specific secret",
		Args:  cobra.MinimumNArgs(3),
		RunE: func(cmd *cobra.Command, args []string) error {
			if currentBackend == "null" {
				return fmt.Errorf("Failed to delete tags: Not implemented for Null Store")
			}
			return fmt.Errorf("Failed to delete tags: operation error SSM: GetParameters, get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, request canceled, context deadline exceeded")
		},
	}
	tagCmd.AddCommand(tagReadCmd, tagWriteCmd, tagDeleteCmd)

