# Old's single suggests original was built with older cobra that didn't add extra newline.
# To match old, we need to trim one newline from error output when it ends with \n\n.

# We can implement a custom writer for stderr that collapses trailing double newline to single?
# Or we can set SilenceErrors=true and manually handle error printing to ensure single newline.

# Let's implement a wrapper that intercepts stderr writes and post-processes.

cat > /tmp/wrapper_test.go <<'GO'
package main

import (
    "os"
    "bytes"
    "github.com/spf13/cobra"
)

type trimWriter struct {
    w bytes.Buffer
}

func (t *trimWriter) Write(p []byte) (n int, err error) {
    // Just buffer
    return t.w.Write(p)
}

func main(){
    root := &cobra.Command{
        Use:"chamber [command]",
        Short:"CLI for storing secrets",
        SilenceErrors: true,
        SilenceUsage: false,
    }
    root.PersistentFlags().StringP("backend","b","ssm","Backend")
    c := &cobra.Command{
        Use:"list <service>",
        Short:"List the secrets set for a service",
        Args: cobra.ExactArgs(1),
        Run: func(cmd *cobra.Command, args []string){},
    }
    c.Flags().BoolP("expand","e",false,"Expand")
    root.AddCommand(c)
    // Capture via custom error handling
    root.SetArgs(os.Args[1:])
    // Override error handling: Execute returns error, we print ourselves
    var buf bytes.Buffer
    root.SetErr(&buf)
    root.SetOut(&buf)
    err := root.Execute()
    if err != nil {
        // Cobra with SilenceErrors true won't print error automatically, we need to print error + usage ourselves
        // But we need to determine if error is arg error (should show usage) vs custom (should not)?
        // For now just print error and usage if not silenced
        // For arg error, we want to print error + usage (UsageString from failing command)
        // How to know which command failed? root.Execute returns error but not command.
        // We can use root's `Suggestions`? Not.
        // Instead we can keep SilenceErrors false and SilenceUsage false, but wrap stderr to trim extra newline after execution?
        // Simpler: keep default behavior but post-process stderr file after execution?
        // But we can't easily intercept cobra's direct write to os.Stderr if we don't set SetErr.
        // Cobra's error printing uses cmd.ErrOrStderr() which defaults to os.Stderr if not set.
        // So if we set SetErr to a buffer, we can capture and then post-process to trim double newline.
        // Then write to actual os.Stderr.
        // Let's do that: set SetErr to buffer, execute, then if buf ends with \n\n, trim to \n, then write to os.Stderr.
        out := buf.String()
        // Trim extra newline at end if double
        if len(out) >=2 && out[len(out)-1]=='\n' && out[len(out)-2]=='\n' {
            // Check if original would have single? For help, it ends with single, not double, so we only trim for error case where double?
            // For error case, out is "Error: ...\nUsage:\n ...\n\n" (ends double). For help case, out is not via error, but via Help() which goes to SetOut, not SetErr.
            // So trimming is safe for error case.
            out = out[:len(out)-1]
        }
        os.Stderr.WriteString(out)
        if err != nil {
            os.Exit(1)
        }
    } else {
        // For success case, output was already in buf? But we set both SetOut and SetErr to same buf, so need to flush?
        // This approach gets messy.
        os.Stderr.WriteString(buf.String())
    }
}
