cat > /tmp/test_normalize.go <<'GO'
package main
import (
    "fmt"
    "github.com/spf13/cobra"
    "github.com/spf13/pflag"
)
type chamberWriteValue struct {val bool}
func (c *chamberWriteValue) String() string { if c.val {return "true"}; return "false" }
func (c *chamberWriteValue) Set(s string) error { fmt.Printf("Set called with %q\n", s); c.val=true; return nil }
func (c *chamberWriteValue) Type() string { return "chamber write" }
func main(){
    root := &cobra.Command{Use:"test", Short:"test"}
    var v chamberWriteValue
    root.Flags().Var(&v, "normalize-keys", "help")
    // Try to set NoOptDefVal
    root.Flags().Lookup("normalize-keys").NoOptDefVal = "true"
    root.SetArgs([]string{"--normalize-keys"})
    // Simulate parsing
    err := root.PersistentFlags().Parse([]string{"--normalize-keys"})
    fmt.Printf("err %v\n", err)
    fmt.Printf("val %v\n", v.val)
    // Also try via cobra
    root.SetArgs([]string{"import","svc","file","--normalize-keys"})
    // Need to add subcommand
    imp := &cobra.Command{Use:"import", Short:"import", Run: func(cmd *cobra.Command, args []string){ fmt.Println("run")}}
    imp.Flags().Var(&v, "normalize-keys", "help")
    imp.Flags().Lookup("normalize-keys").NoOptDefVal = "true"
    root.AddCommand(imp)
    root.SetArgs([]string{"import","svc","file","--normalize-keys"})
    err = root.Execute()
    fmt.Printf("execute err %v\n", err)
}
GO
go run /tmp/test_normalize.go 2>&1 | head -n 20
"}

